"""Package and test a clean committed library snapshot; never publish or upload."""

import argparse
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import shutil
import subprocess
import tarfile
import tempfile
import tomllib

ROOT = Path(__file__).resolve().parents[2]
PACKAGE = "agent-skills-kit"


def package_listing(output, windows):
    # Cargo's human --list prints native relative paths, while tar member names
    # are portable POSIX paths. Normalize only the Windows CLI observation.
    entries = [line.replace("\\", "/") if windows else line for line in output.splitlines()]
    if len(entries) != len(set(entries)):
        raise ValueError("duplicate normalized package-list paths")
    return entries


def inspect_archive(archive, prefix):
    """Validate every entry before extracting an archive generated by Cargo."""
    members = archive.getmembers()
    if len(members) > 1024 or sum(member.size for member in members) > 16 * 1024 * 1024:
        raise ValueError("package archive exceeds reviewed inspection limits")
    seen = set()
    for member in members:
        path = PurePosixPath(member.name)
        if (not member.isfile() or path.is_absolute() or ".." in path.parts
                or not path.parts or path.parts[0] != prefix or len(path.parts) < 2
                or member.name != path.as_posix() or "\\" in member.name or ":" in member.name
                or any(ord(char) < 32 or ord(char) == 127 for char in member.name)
                or member.name in seen):
            raise ValueError("unsafe or duplicate package entry")
        if any(part.startswith(".") for part in path.parts[1:]) and path.parts[1:] != (".cargo_vcs_info.json",):
            raise ValueError("unexpected hidden package entry")
        seen.add(member.name)
    return members


def rehearse(toolchain):
    workspace = tomllib.loads((ROOT / "Cargo.toml").read_text(encoding="utf-8"))
    pin = tomllib.loads((ROOT / "rust-toolchain.toml").read_text(encoding="utf-8"))["toolchain"]["channel"]
    if toolchain not in (pin, workspace["workspace"]["package"]["rust-version"], "stable"):
        raise ValueError("use the committed development pin, MSRV or stable CI toolchain")
    installed = subprocess.run(["rustup", "toolchain", "list"], check=True,
                               capture_output=True, text=True).stdout.splitlines()
    if not any(line.split()[0] == toolchain or line.startswith(toolchain + "-") for line in installed):
        raise ValueError("requested toolchain is not installed; this rehearsal never installs it")
    if workspace["workspace"]["package"]["publish"] is not False:
        raise ValueError("development publish=false gate must remain in place")
    git_environment = dict(os.environ, GIT_CONFIG_GLOBAL=os.devnull,
                           GIT_CONFIG_NOSYSTEM="1", GIT_TERMINAL_PROMPT="0")

    def git(*args, cwd=ROOT):
        return subprocess.run(["git", "-c", "core.hooksPath=" + os.devnull,
                               "-c", "init.templateDir=", *args], cwd=cwd, env=git_environment,
                              check=True, capture_output=True, text=True, timeout=30).stdout.strip()

    if git("status", "--porcelain", "--untracked-files=no"):
        raise ValueError("commit tracked changes before rehearsing; untracked local data is never cloned")
    revision = git("rev-parse", "HEAD")
    version = workspace["workspace"]["package"]["version"]
    with tempfile.TemporaryDirectory(prefix="ask-library-package-") as temporary:
        root = Path(temporary).resolve()
        snapshot = root / "snapshot"
        git("clone", "--quiet", "--no-hardlinks", "--no-checkout", str(ROOT), str(snapshot))
        git("checkout", "--quiet", "--detach", revision, cwd=snapshot)
        environment = dict(git_environment, RUSTUP_TOOLCHAIN=toolchain, CARGO_TARGET_DIR=str(root / "build"))

        def cargo(*args, cwd=snapshot, capture=False):
            return subprocess.run(["cargo", *args], cwd=cwd, env=environment,
                                  check=True, capture_output=capture, text=True, timeout=600)

        rustc = subprocess.run(["rustc", "-Vv"], cwd=snapshot, env=environment,
                               check=True, capture_output=True, text=True).stdout.strip()
        package = snapshot / "crates" / PACKAGE
        copies = {"LICENSE-MIT": snapshot / "LICENSE-MIT", "LICENSE-APACHE": snapshot / "LICENSE-APACHE"}
        for name in ("ChenYuheng-MIT", "Ethiraric-MIT"):
            copies["third-party/saphyr-parser-0.2.2/" + name] = snapshot / "docs/third-party/saphyr-parser-0.2.2" / name
        for destination, original in copies.items():
            if (package / destination).read_bytes() != original.read_bytes():
                raise ValueError("package license/notice copy differs from the approved original")
        listing = package_listing(cargo("package", "-p", PACKAGE, "--list", "--locked", "--offline", capture=True).stdout,
                                  windows=os.name == "nt")
        required = {"Cargo.toml", "Cargo.lock", "README.md", "src/catalog/bundled.rs",
                    "src/catalog/data/expanded.json", *copies}
        if not required <= set(listing):
            raise ValueError(f"package list omits required files: {sorted(required - set(listing))}")
        cargo("package", "-p", PACKAGE, "--locked", "--offline")
        artifact = root / "build/package" / f"{PACKAGE}-{version}.crate"
        prefix = f"{PACKAGE}-{version}"
        unpack = root / "unpack"
        unpack.mkdir()
        with tarfile.open(artifact, "r:gz") as archive:
            members = inspect_archive(archive, prefix)
            if {member.name.removeprefix(prefix + "/") for member in members} != set(listing):
                raise ValueError("actual archive differs from the inspected cargo package list")
            for member in members:
                destination = unpack.joinpath(*PurePosixPath(member.name).parts)
                destination.parent.mkdir(parents=True, exist_ok=True)
                with archive.extractfile(member) as source, destination.open("xb") as output:
                    shutil.copyfileobj(source, output)
        library = unpack / prefix
        normalized = tomllib.loads((library / "Cargo.toml").read_text(encoding="utf-8"))
        if normalized["package"]["publish"] is not False:
            raise ValueError("packaged manifest lost publish=false")
        vcs = json.loads((library / ".cargo_vcs_info.json").read_text(encoding="utf-8"))
        if vcs["git"]["sha1"] != revision or vcs["git"].get("dirty", False):
            raise ValueError("package VCS identity is not the clean candidate revision")
        for name in (*copies, "README.md", "src/catalog/bundled.rs", "src/catalog/data/expanded.json"):
            if (library / name).read_bytes() != (package / name).read_bytes():
                raise ValueError("packaged runtime/notice/README bytes differ from the candidate")
        cargo("check", "--manifest-path", str(library / "Cargo.toml"), "--all-targets",
              "--no-default-features", "--locked", "--offline")
        cargo("test", "--manifest-path", str(library / "Cargo.toml"), "--all-features", "--locked", "--offline")
        cargo("doc", "--manifest-path", str(library / "Cargo.toml"), "--no-deps", "--locked", "--offline")
        consumer = root / "consumer"
        consumer.mkdir()
        source_consumer = snapshot / "examples/external-consumer"
        shutil.copytree(source_consumer / "src", consumer / "src")
        shutil.copyfile(source_consumer / "Cargo.lock", consumer / "Cargo.lock")
        manifest = (source_consumer / "Cargo.toml").read_text(encoding="utf-8")
        old = 'path = "../../crates/agent-skills-kit"'
        if manifest.count(old) != 1:
            raise ValueError("external consumer dependency shape changed; review the rehearsal")
        (consumer / "Cargo.toml").write_text(manifest.replace(old, "path = " + json.dumps(library.as_posix())), encoding="utf-8")
        cargo("test", "--manifest-path", str(consumer / "Cargo.toml"), "--locked", "--offline")
        return {"candidate": revision, "toolchain": rustc, "files": listing,
                "crate_sha256": hashlib.sha256(artifact.read_bytes()).hexdigest(),
                "crate_bytes": artifact.stat().st_size, "publish": False,
                "result": "package verified; unpacked library tests/docs and external consumer passed"}


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--toolchain", required=True)
    arguments = parser.parse_args()
    print(json.dumps(rehearse(arguments.toolchain), sort_keys=True))
